package fr.xerion.xrnhud.mixin;
import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;import fr.xerion.xrnhud.*;
@Mixin(net.minecraft.client.renderer.entity.ItemEntityRenderer.class) public abstract class ItemScaleDropMixin {
 @Inject(method="extractRenderState(Lnet/minecraft/world/entity/item/ItemEntity;Lnet/minecraft/client/renderer/entity/state/ItemEntityRenderState;F)V",at=@At("RETURN"),require=1)private void xrn$state(net.minecraft.world.entity.item.ItemEntity entity,net.minecraft.client.renderer.entity.state.ItemEntityRenderState state,float delta,CallbackInfo ci){((DroppedItemScale)(Object)state).xrn$dropScale(TailleObjets.auSol(entity.getItem()));}
 @Inject(method="submit(Lnet/minecraft/client/renderer/entity/state/ItemEntityRenderState;Lcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/SubmitNodeCollector;Lnet/minecraft/client/renderer/state/level/CameraRenderState;)V",at=@At("HEAD"),require=1)private void xrn$scale(net.minecraft.client.renderer.entity.state.ItemEntityRenderState state,com.mojang.blaze3d.vertex.PoseStack matrices,net.minecraft.client.renderer.SubmitNodeCollector queue,net.minecraft.client.renderer.state.level.CameraRenderState camera,CallbackInfo ci){float f=((DroppedItemScale)(Object)state).xrn$dropScale();matrices.pushPose();matrices.scale(f,f,f);}
 @Inject(method="submit(Lnet/minecraft/client/renderer/entity/state/ItemEntityRenderState;Lcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/SubmitNodeCollector;Lnet/minecraft/client/renderer/state/level/CameraRenderState;)V",at=@At("RETURN"),require=1)private void xrn$restore(net.minecraft.client.renderer.entity.state.ItemEntityRenderState state,com.mojang.blaze3d.vertex.PoseStack matrices,net.minecraft.client.renderer.SubmitNodeCollector queue,net.minecraft.client.renderer.state.level.CameraRenderState camera,CallbackInfo ci){matrices.popPose();}
}
